@keyframes pulse { 50% { opacity: .35; } }
.live:focus-visible, .chart:focus-visible, .watch:focus-visible, .cancel:focus-visible { outline: var(--focus-outline-width, 2px) solid var(--focus-outline, var(--accent)); outline-offset: var(--focus-outline-offset, 2px); }
