.ma2 { fill: none; stroke: var(--series-2); stroke-width: 1.5; }
.crosshair { stroke: var(--border-strong); stroke-width: 1; stroke-dasharray: 3 3; }
.lastLine { stroke-width: 1; stroke-dasharray: 2 3; stroke: var(--text-muted); }
.lastLine[data-dir="up"] { stroke: var(--success); }
.lastLine[data-dir="down"] { stroke: var(--danger); }
.lastTag { fill: var(--text-muted); }
.lastTag[data-dir="up"] { fill: var(--success); }
.lastTag[data-dir="down"] { fill: var(--danger); }
.lastText { fill: var(--surface); font-size: 10px; font-weight: 600; font-variant-numeric: tabular-nums; }
.side { display: grid; gap: var(--space-4); min-width: 0; align-content: start; }
.side h4 { margin: 0 0 var(--space-2); font-size: var(--text-sm); font-weight: 500; }
.watchlist { display: grid; gap: 2px; }
.watch { display: grid; grid-template-columns: minmax(0, 1fr) 3.5rem auto; align-items: center; gap: var(--space-2); width: 100%; min-height: 3rem; padding: var(--space-1) var(--space-2); border: 0; border-radius: var(--radius-control); background: transparent; color: inherit; font: inherit; text-align: left; cursor: pointer; transition: background var(--duration-standard) var(--ease-standard); }
